(function(){
 const DB='zwconnect-offline-actions',STORE='actions',BOUND_ROLES=new Set(['customer','worker','shop_owner','site_admin','courier','applicant']);
 const listeners=new Set();let syncing=false,context='public',identity={userId:null,email:null,shopId:null};
 const deviceId=(()=>{let id=localStorage.getItem('zwconnect-device-id');if(!id){id=crypto.randomUUID();localStorage.setItem('zwconnect-device-id',id)}return id})();
 function openDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open(DB,1);request.onupgradeneeded=()=>{const store=request.result.createObjectStore(STORE,{keyPath:'id'});store.createIndex('createdAt','createdAt')};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
 async function all(){const db=await openDb(),items=await new Promise((resolve,reject)=>{const request=db.transaction(STORE).objectStore(STORE).getAll();request.onsuccess=()=>resolve(request.result.sort((a,b)=>a.createdAt.localeCompare(b.createdAt)));request.onerror=()=>reject(request.error)});db.close();return items}
 async function put(item){const db=await openDb();await new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(item);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
 async function remove(id){const db=await openDb();await new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
 function roleMatches(action){return action.role===context||(context==='public'&&action.role==='applicant')||(context==='customer'&&action.role==='public')||(context==='shop_owner'&&action.type==='sale.create')}
 function needsActor(action){return BOUND_ROLES.has(action.role)||['sale.create','stock_purchase.record','purchase_expense.record','customer_order.review'].includes(action.type)}
 function belongsToIdentity(action){if(!needsActor(action))return true;if(!action.actorId||!identity.userId||action.actorId!==identity.userId)return false;if(action.shopId&&identity.shopId&&action.shopId!==identity.shopId)return false;return true}
 function canProcess(action){return roleMatches(action)&&belongsToIdentity(action)}
 async function snapshot(){const stored=await all(),items=stored.filter(canProcess),locked=stored.filter(x=>needsActor(x)&&!belongsToIdentity(x));return{online:navigator.onLine,syncing,pending:items.length,failed:items.filter(x=>x.status==='failed').length,blocked:items.filter(x=>x.status==='blocked').length,locked:locked.length,totalStored:stored.length,items}}
 async function notify(){const value=await snapshot();listeners.forEach(fn=>{try{fn(value)}catch{}});window.dispatchEvent(new CustomEvent('zwconnect:offline-status',{detail:value}));return value}
 function client(){return window.zwconnectSupabase||null}
 async function sessionIdentity(){const db=client();if(!db)return identity;try{const {data}=await db.auth.getSession(),u=data?.session?.user;return{...identity,userId:u?.id||null,email:u?.email||null}}catch{return identity}}
 async function refreshIdentity(details={}){const derived=details.force?identity:await sessionIdentity();identity={...derived,...details};delete identity.force;window.dispatchEvent(new CustomEvent('zwconnect:identity-change',{detail:{...identity,role:context,deviceId}}));return identity}
 async function rpc(name,args){const db=client();if(!db)throw new Error('Supabase connection is not configured');const {data,error}=await db.rpc(name,args);if(error)throw error;return data}
 async function send(action){const p=action.payload;
  if(action.type==='sale.create')return rpc('create_offline_sale',{client_event_uuid:action.id,target_shop:p.shopId,cart_items:p.items,payment_method:p.paymentMethod,sale_total:p.total,sold_at:p.soldAt,source_device:p.deviceId});
  if(action.type==='stock_purchase.record')return rpc('record_stock_purchase',{client_event_uuid:action.id,target_shop:p.shopId,supplier_name:p.supplier,supplier_invoice:p.invoice,payment_source:p.paymentSource,purchased_at:p.purchasedAt,purchase_notes:p.notes||'',purchase_items:p.items});
  if(action.type==='purchase_expense.record')return rpc('record_purchase_expense',{client_event_uuid:action.id,target_shop:p.shopId,expense_category:p.category,expense_amount:p.amount,expense_description:p.description,payment_source:p.paymentSource,expense_date:p.expenseDate});
  if(action.type==='purchasing_permission.set')return rpc('set_worker_purchasing_permission',{target_shop:p.shopId,target_worker_user:p.workerUserId,worker_email:p.workerEmail||'',allow_purchases:!!p.canPurchase,allow_expenses:!!p.canRecordExpenses});
  if(action.type==='worker.invite'){const invitationId=await rpc('queue_worker_invitation',{client_event_uuid:action.id,target_shop:p.shopId,worker_name:p.name,worker_email:p.email,worker_job:p.job}),db=client();const {error}=await db.functions.invoke('process-worker-invitation',{body:{invitation_id:invitationId}});if(error)throw error;return invitationId}
  if(action.type==='application.review')return rpc('review_owner_application_offline',{client_event_uuid:action.id,application_uuid:p.applicationId,decision:p.decision,rejection_note:p.reason||null,requested_slug:p.slug||null});
  if(action.type==='shop.update')return rpc('update_shop_offline',{client_event_uuid:action.id,target_shop:p.shopId,shop_changes:p.changes});
  if(action.type==='shop.delete')return rpc('delete_shop_offline',{client_event_uuid:action.id,target_shop:p.shopId});
  if(action.type==='subscription.update')return rpc('set_shop_subscription_offline',{client_event_uuid:action.id,target_shop:p.shopId,subscription_amount:p.amount,subscription_duration_days:p.duration,trial_days:p.trial,new_status:p.status});
  if(action.type==='customer_order.submit')return rpc('submit_customer_payment',{client_event_uuid:action.id,target_shop:p.shopId,customer_name:p.customerName,customer_phone:p.phone,customer_email:p.email||'',target_payment_method:p.paymentMethodId,payment_reference:p.reference,cart_items:p.items,wants_delivery:!!p.delivery,delivery_address:p.deliveryAddress||null,delivery_city:p.deliveryCity||null});
  if(action.type==='cart_order.submit'){
   let proofPath=null;const db=client();if(!db)throw new Error('Supabase connection is not configured');const {data:userData,error:userError}=await db.auth.getUser();if(userError||!userData?.user)throw userError||new Error('Sign in with a customer account before syncing this order');if(p.proofImage){proofPath=`${userData.user.id}/${action.id}/${p.proofImage.name.replace(/[^a-zA-Z0-9._-]/g,'-')}`;const upload=await db.storage.from('payment-proofs').upload(proofPath,p.proofImage,{contentType:p.proofImage.type,upsert:true});if(upload.error)throw upload.error}
   return rpc('submit_cart_payment',{client_event_uuid:action.id,tracking_uuid:p.trackingToken,target_shop:p.shopId,customer_name:p.customerName,customer_phone:p.phone,customer_email:p.email||'',target_payment_method:p.paymentMethodId,payment_reference:p.reference,payment_proof_path:proofPath,payment_proof_text:p.proofText||'',cart_items:p.items});
  }
  if(action.type==='customer_order.review')return rpc('review_customer_payment',{order_uuid:p.orderId,approve:!!p.approve,decision_note:p.note||p.reason||'Reviewed by shop'});
  if(action.type==='delivery.request')return rpc('request_order_delivery',{order_uuid:p.orderId,tracking_uuid:p.trackingToken,dropoff_address:p.address,dropoff_lat:p.latitude,dropoff_lng:p.longitude,parcel_description:p.parcel||''});
  if(action.type==='delivery_bid.decide')return rpc('decide_delivery_bid',{order_uuid:p.orderId,tracking_uuid:p.trackingToken,target_bid:p.bidId,accept_bid:!!p.accept});
  if(action.type==='delivery_bid.submit')return rpc('submit_delivery_bid',{target_delivery:p.deliveryId,offered_amount:p.offeredFee,bid_note:p.note||'',courier_lat:p.latitude,courier_lng:p.longitude});
  if(action.type==='payment_method.save')return rpc('save_shop_payment_method',{target_shop:p.shopId,method_details:p.method});
  if(action.type==='courier_rate.save')return rpc('save_courier_rate',{rate_details:p.rate});
  if(action.type==='courier_application.review')return rpc('approve_courier_application',{application_uuid:p.applicationId,approve:!!p.approve,rejection_note:p.reason||null});
  if(action.type==='courier_subscription.update')return rpc('set_courier_subscription',{target_courier:p.courierId,subscription_amount:p.amount,subscription_duration_days:p.duration,trial_days:p.trial,new_status:p.status});
  if(action.type==='subscription.bulk_update')return rpc('set_all_platform_subscriptions',{apply_to_shops:!!p.applyShops,apply_to_couriers:!!p.applyCouriers,shop_amount:p.shopAmount,courier_amount:p.courierAmount,subscription_duration_days:p.duration,trial_days:p.trial,new_status:p.status});
  if(action.type==='profile.create')return rpc('admin_create_business_profile',{profile_id:p.id,profile_title:p.title,profile_icon:p.icon,profile_description:p.description,profile_order:p.order||0});
  if(action.type==='profile.update')return rpc('admin_update_business_profile',{profile_id:p.id,profile_title:p.title,profile_icon:p.icon,profile_description:p.description,profile_order:p.order||0,profile_enabled:p.enabled!==false});
  if(action.type==='profile.delete')return rpc('admin_delete_business_profile',{target_profile:p.id});
  if(action.type==='support.submit')return rpc('submit_support_ticket',{client_event_uuid:action.id,requester_name:p.name,requester_email:p.email||'',requester_phone:p.phone||'',ticket_category:p.category,ticket_subject:p.subject,ticket_message:p.message,requester_role:p.role||'public'});
  if(action.type==='support_ticket.update')return rpc('admin_update_support_ticket',{ticket_id:p.ticketId,new_status:p.status,decision_note:p.note||'',priority_level:p.priority||'normal'});
  if(action.type==='subscription_request.submit')return rpc('submit_subscription_request',{client_event_uuid:action.id,target_shop:p.shopId,request_kind:p.type,extension_days:p.days||null,request_note:p.note||''});
  if(action.type==='subscription_request.review')return rpc('admin_review_subscription_request',{request_uuid:p.requestId,approve:!!p.approve,decision_note:p.note||''});
  if(action.type==='shop_image.add'){
   const db=client();if(!db)throw new Error('Supabase connection is not configured');const path=`${p.shopId}/${action.id}/${p.file.name.replace(/[^a-zA-Z0-9._-]/g,'-')}`,upload=await db.storage.from('shop-images').upload(path,p.file,{contentType:p.file.type,upsert:true});if(upload.error)throw upload.error;return rpc('save_shop_image',{image_uuid:p.imageId,target_shop:p.shopId,object_path:path,alt_text:p.alt||'',requested_position:p.position});
  }
  if(action.type==='shop_image.delete'){const path=await rpc('delete_shop_image',{image_uuid:p.imageId});const db=client();if(path&&db){const result=await db.storage.from('shop-images').remove([path]);if(result.error)throw result.error}return path}
  if(action.type==='delivery.status')return rpc('courier_update_delivery_status',{delivery_uuid:p.deliveryId,new_status:p.status});
  if(action.type==='delivery.received')return rpc('customer_confirm_delivery',{order_uuid:p.orderId,tracking_uuid:p.trackingToken});
  if(action.type==='courier_application.submit'){
   const db=client();if(!db)throw new Error('Supabase connection is not configured');const {data:userData,error:userError}=await db.auth.getUser();if(userError||!userData?.user)throw userError||new Error('Sign in before syncing this courier application');
   const proof=p.proof,path=`${userData.user.id}/${action.id}/${proof.name.replace(/[^a-zA-Z0-9._-]/g,'-')}`;const upload=await db.storage.from('courier-proofs').upload(path,proof,{contentType:proof.type,upsert:true});if(upload.error)throw upload.error;
   return rpc('submit_courier_application',{full_name:p.name,business_name:p.business,applicant_email:p.email,applicant_phone:p.phone,applicant_national_id:p.nationalId,bicycle_details:p.bike,operating_city:p.city,uploaded_proof_path:path});
  }
  if(action.type==='owner_application.submit'){
   const db=client();if(!db)throw new Error('Supabase connection is not configured');const {data:userData,error:userError}=await db.auth.getUser();if(userError||!userData?.user)throw userError||new Error('Sign in before syncing this application');
   const userId=userData.user.id,proof=p.proof,path=`${userId}/${action.id}/${proof.name.replace(/[^a-zA-Z0-9._-]/g,'-')}`;
   const upload=await db.storage.from('shop-proofs').upload(path,proof,{contentType:proof.type,upsert:true});if(upload.error)throw upload.error;
   return rpc('submit_owner_application_offline',{client_event_uuid:action.id,owner_name:p.owner,owner_email:p.email,owner_phone:p.phone,business_name:p.business,business_profile:p.profile,business_city:p.city,business_address:p.address,store_sales_mode:p.salesMode||'retail',uploaded_proof_path:path,uploaded_proof_name:proof.name,uploaded_proof_mime:proof.type,uploaded_proof_size:proof.size});
  }
  throw new Error(`Unsupported offline action: ${action.type}`)
 }
 async function enqueue(type,payload,options={}){await refreshIdentity(options.identity||{});const customerActions=['customer_order.submit','cart_order.submit','delivery.request','delivery_bid.decide','delivery.received'],role=customerActions.includes(type)?'customer':options.role||'public',bound=BOUND_ROLES.has(role)||['sale.create','stock_purchase.record','purchase_expense.record','customer_order.review'].includes(type),actorId=options.actorId||identity.userId||null,shopId=options.shopId||payload.shopId||payload.targetShop||identity.shopId||null,item={id:options.id||crypto.randomUUID(),type,payload,role,actorId,shopId,deviceId,createdAt:new Date().toISOString(),status:bound&&!actorId?'blocked':'pending',attempts:0,lastError:bound&&!actorId?'Sign in to the original account before this action can sync.':''};await put(item);await notify();if(navigator.onLine&&options.auto!==false&&item.status!=='blocked')flush();return item}
 async function verifyAuthenticatedActor(){const db=client();if(!db)return null;const {data,error}=await db.auth.getUser();if(error||!data?.user)return null;identity={...identity,userId:data.user.id,email:data.user.email||null};return data.user}
 async function flush(){if(syncing||!navigator.onLine)return snapshot();const user=await verifyAuthenticatedActor();if(!user){await notify();return snapshot()}syncing=true;await notify();for(const action of (await all()).filter(canProcess)){if(action.actorId!==user.id){action.status='blocked';action.lastError='Locked to the account that originally created this action.';await put(action);continue}action.status='syncing';action.attempts=(action.attempts||0)+1;action.lastAttemptAt=new Date().toISOString();await put(action);await notify();try{await send(action);await remove(action.id)}catch(error){action.status=/sign in|not authorised|permission|role|account/i.test(error?.message||'')?'blocked':'failed';action.lastError=String(error?.message||error).slice(0,300);await put(action);if(action.status==='failed')break}}syncing=false;return notify()}
 function subscribe(fn){listeners.add(fn);snapshot().then(fn);return()=>listeners.delete(fn)}
 async function retry(id){const item=(await all()).find(x=>x.id===id);if(item){item.status='pending';item.lastError='';await put(item)}return flush()}
 async function visibleList(){return(await all()).filter(item=>!needsActor(item)||belongsToIdentity(item))}
 window.addEventListener('online',flush);window.addEventListener('offline',notify);
 async function setContext(role,details={}){context=role||'public';await refreshIdentity(details);await notify();if(navigator.onLine&&identity.userId)flush();return{role:context,...identity,deviceId}}
 function currentIdentity(){return{role:context,...identity,deviceId}}
 window.ZWOffline={enqueue,flush,retry,list:visibleList,status:snapshot,subscribe,setContext,identity:currentIdentity};
})();
